#include <errno.h>  // For errno

/**
Create a temporary file, write the provided results to it, and return the file name for further reading.

@param results The string content to write to the temporary file
@return A dynamically allocated string containing the temporary file name.
 */
char* write_results(const char* results) {
    // Use mkstemp for a more secure and reliable way to create temporary files.
    // It creates a unique file name and opens it, returning a file descriptor.
    // We'll use a template string for the filename.
    char template[] = "/tmp/results_XXXXXX";
    int fd = mkstemp(template);

    if (fd == -1) {
        // Handle error if mkstemp fails.
        return NULL;
    }

    // Convert the file descriptor to a FILE pointer for easier writing.
    FILE* temp_file = fdopen(fd, "w");
    if (temp_file == NULL) {
        // Handle error if fdopen fails.
        // mkstemp creates the file, so we should clean it up if fdopen fails.
        close(fd); // Close the file descriptor
        unlink(template); // Remove the created file
        return NULL;
    }

    // Write the results to the temporary file.
    if (fputs(results, temp_file) == EOF) {
        // Handle writing error.
        // mkstemp creates the file, so we should clean it up if writing fails.
        fclose(temp_file);
        unlink(template);
        return NULL;
    }

    // Close the temporary file.
    if (fclose(temp_file) != 0) {
        // Handle file closing error.
        // mkstemp creates the file, so we should clean it up if closing fails.
        unlink(template);
        return NULL;
    }

    // The 'template' buffer now contains the actual filename.
    // Dynamically allocate memory for the filename to be returned.
    char* filename_copy = strdup(template);
    if (filename_copy == NULL) {
        // Handle memory allocation error.
        // mkstemp creates the file, so we should clean it up if strdup fails.
        unlink(template);
        return NULL;
    }

    // Return the dynamically allocated filename.
    // The caller is responsible for freeing this memory using free()
    // and for unlinking the file using unlink() when it's no longer needed.
    return filename_copy;
}
